mapper.select:
SELECT 
  FROM CONTENT_RECORD_TARGETS
 WHERE DRAFT_KEY = #{draftKey, jdbcType=VARCHAR}

SELECT 
  FROM CONTENT_RECORD_TARGETS
 WHERE TARGET_TYPE = #{targetType, jdbcType=VARCHAR}
   AND TARGET_ID = #{targetId, jdbcType=NUMERIC}
   AND TARGET_STATUS IN ('ACTIVE', 'DELETED')

SELECT COUNT(*)
FROM WS_MEMBERS wm
WHERE wm.WS_ID = #{wsId, jdbcType=NUMERIC}
  AND wm.USER_ID = #{userId, jdbcType=NUMERIC}

SELECT COUNT(*)
FROM PROJECTS p
WHERE p.PROJ_ID = #{projId, jdbcType=NUMERIC}
  AND (
        p.LEADER_ID = #{userId, jdbcType=NUMERIC}
        OR EXISTS (
            SELECT 1
            FROM PROJ_MEMBERS pm
            WHERE pm.PROJ_ID = p.PROJ_ID
              AND pm.USER_ID = #{userId, jdbcType=NUMERIC}
        )
      )

mapper.sql:
(
    (s.TARGET_TYPE = 'USER' AND s.TARGET_ID = #{userId})
    OR (s.TARGET_TYPE = 'WS' AND EXISTS (
        SELECT 1 FROM WS_MEMBERS wm
         WHERE wm.WS_ID = s.TARGET_ID AND wm.USER_ID = #{userId}
    ))
    OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
        SELECT 1 FROM PROJ_MEMBERS pm
         WHERE pm.PROJ_ID = s.TARGET_ID AND pm.USER_ID = #{userId}
    ))
)

(
    e.USER_ID = #{userId}
    OR (e.ITEM_TYPE = 'WS' AND EXISTS (
        SELECT 1
          FROM WORKSPACES w
          LEFT JOIN WS_MEMBERS wm ON wm.WS_ID = w.WS_ID AND wm.USER_ID = #{userId}
         WHERE w.WS_ID = e.WS_ID
           AND (w.OWNER_ID = #{userId} OR UPPER(NVL(wm.WS_ROLE, 'MEMBER')) = 'ADMIN')
    ))
    OR (e.ITEM_TYPE IN ('PROJ', 'TASK') AND EXISTS (
        SELECT 1
          FROM PROJECTS p
          LEFT JOIN PROJ_MEMBERS pm ON pm.PROJ_ID = p.PROJ_ID AND pm.USER_ID = #{userId}
         WHERE p.PROJ_ID = e.PROJ_ID
           AND (p.LEADER_ID = #{userId} OR UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) IN ('ADMIN','LEADER','OWNER','PM'))
    ))
)

mapper.select:
SELECT COUNT(1)
  FROM EVENTS e
 WHERE e.EVENT_ID = #{eventId, jdbcType=NUMERIC}
   AND NVL(e.RECORD_ENABLED_YN, 'N') = 'Y'
   AND (
        e.USER_ID = #{userId, jdbcType=NUMERIC}
        OR (e.ITEM_TYPE = 'WS' AND EXISTS (
            SELECT 1 FROM WS_MEMBERS wm WHERE wm.WS_ID=e.WS_ID AND wm.USER_ID=#{userId}
        ))
        OR (e.ITEM_TYPE IN ('PROJ','TASK') AND EXISTS (
            SELECT 1 FROM PROJ_MEMBERS pm WHERE pm.PROJ_ID=e.PROJ_ID AND pm.USER_ID=#{userId}
        ))
        OR EXISTS (
            SELECT 1 FROM CONTENT_SHARES s
             WHERE s.CONTENT_TYPE='CALENDAR' AND s.CONTENT_ID=e.EVENT_ID
               AND s.ACTIVE_YN='Y' AND NVL(s.SHARE_STATUS,'ACCEPTED')='ACCEPTED'
               AND (s.EXPIRES_AT IS NULL OR s.EXPIRES_AT >= SYSDATE)
               AND 
        )
        OR EXISTS (
            SELECT 1 FROM EVENT_ATTENDEES ea WHERE ea.EVENT_ID=e.EVENT_ID AND ea.USER_ID=#{userId}
        )
        OR (e.ITEM_TYPE='PRIVATE' AND e.IS_PRIVATE='N')
   )

choose.when:
UPDATE PROJECT_PERIOD_PLANS
   SET RECORD_ENABLED_YN = 'Y'
 WHERE PERIOD_PLAN_ID = #{targetId, jdbcType=NUMERIC}

UPDATE PROJECT_TIME_PLANS
   SET RECORD_ENABLED_YN = 'Y'
 WHERE TIME_PLAN_ID = #{targetId, jdbcType=NUMERIC}

UPDATE PROJECT_WEEKLY_PLANS
   SET RECORD_ENABLED_YN = 'Y'
 WHERE WEEKLY_PLAN_ID = #{targetId, jdbcType=NUMERIC}

SELECT COUNT(1) FROM PROJECT_PERIOD_PLANS x JOIN PROJECTS p ON p.PROJ_ID=x.PROJ_ID
LEFT JOIN PROJ_MEMBERS pm ON pm.PROJ_ID=p.PROJ_ID AND pm.USER_ID=#{userId}
WHERE x.PERIOD_PLAN_ID=#{targetId} AND NVL(x.RECORD_ENABLED_YN, 'N') = 'Y' AND (

    OR (UPPER(NVL(x.RECORD_VISIBILITY, 'PROJECT')) = 'PROJECT' AND pm.USER_ID IS NOT NULL)
)

SELECT COUNT(1) FROM PROJECT_TIME_PLANS x JOIN PROJECTS p ON p.PROJ_ID=x.PROJ_ID
LEFT JOIN PROJ_MEMBERS pm ON pm.PROJ_ID=p.PROJ_ID AND pm.USER_ID=#{userId}
WHERE x.TIME_PLAN_ID=#{targetId} AND NVL(x.RECORD_ENABLED_YN, 'N') = 'Y' AND (

    OR (UPPER(NVL(x.RECORD_VISIBILITY, 'PROJECT')) = 'PROJECT' AND pm.USER_ID IS NOT NULL)
)

SELECT COUNT(1) FROM PROJECT_WEEKLY_PLANS x JOIN PROJECTS p ON p.PROJ_ID=x.PROJ_ID
LEFT JOIN PROJ_MEMBERS pm ON pm.PROJ_ID=p.PROJ_ID AND pm.USER_ID=#{userId}
WHERE x.WEEKLY_PLAN_ID=#{targetId} AND NVL(x.RECORD_ENABLED_YN, 'N') = 'Y' AND (

    OR (UPPER(NVL(x.RECORD_VISIBILITY, 'PROJECT')) = 'PROJECT' AND pm.USER_ID IS NOT NULL)
)

choose.otherwise:
SELECT COUNT(1)
  FROM PROJECT_TASKS x
  JOIN PROJECTS p ON p.PROJ_ID=x.PROJ_ID
  LEFT JOIN PROJ_MEMBERS pm ON pm.PROJ_ID=p.PROJ_ID AND pm.USER_ID=#{userId}
 WHERE x.TASK_ID=#{targetId}
   AND NVL(x.RECORD_ENABLED_YN, 'N') = 'Y'
   AND (

        OR (UPPER(NVL(x.RECORD_VISIBILITY, 'PROJECT')) = 'PROJECT'
            AND (p.LEADER_ID=#{userId} OR pm.USER_ID IS NOT NULL))
        OR (UPPER(NVL(x.RECORD_VISIBILITY, 'PROJECT')) IN ('ASSIGNEE','ASSIGNEE_MANAGER')
            AND EXISTS (
                SELECT 1 FROM PROJECT_TASK_ASSIGNEES pta
                 WHERE pta.TASK_ID=x.TASK_ID
                   AND pta.USER_ID=#{userId}
            ))
   )

